import vuedraggable from 'vuedraggable';
export default {
  name: 'c_txt_list',
  props: {
    name: {
      type: String
    },
    configData: {
      type: null
    }
  },
  components: {
    draggable: vuedraggable
  },
  data: function data() {
    return {
      defaults: {},
      itemObj: {},
      datas: this.configData
    };
  },
  mounted: function mounted() {},
  watch: {
    configData: {
      handler: function handler(nVal, oVal) {
        this.datas = nVal;
      },
      deep: true
    }
  },
  methods: {
    addHotTxt: function addHotTxt() {
      if (this.datas[this.name].list.length == 0) {
        this.datas[this.name].list.push(this.itemObj);
      } else {
        var obj = JSON.parse(JSON.stringify(this.datas[this.name].list[this.datas[this.name].list.length - 1]));
        this.datas[this.name].list.push(obj);
      }
    },
    // 删除数组
    bindDelete: function bindDelete(index) {
      if (this.datas[this.name].list.length == 1) {
        this.itemObj = this.datas[this.name].list[0];
      }
      this.datas[this.name].list.splice(index, 1);
    }
  }
};
